import React, { useEffect, useState } from 'react';
import axios from 'axios';

const API_URL = 'http://localhost:3000';

interface Machine {
  id: number;
  name: string;
  status: string;
  production: number;
  temperature: number;
}

interface Alert {
  id: number;
  machine: string;
  type: string;
  message: string;
  createdAt: string;
}

function StatusBadge({ status }: { status: string }) {
  const colors: Record<string, string> = {
    operando: 'bg-green-500',
    manutenção: 'bg-yellow-500',
    falha: 'bg-red-500',
  };
  return (
    <span className={`${colors[status] || 'bg-gray-500'} text-white text-xs px-2 py-1 rounded-full`}>
      {status}
    </span>
  );
}

function App() {
  const [machines, setMachines] = useState<Machine[]>([]);
  const [alerts, setAlerts] = useState<Alert[]>([]);

  useEffect(() => {
    axios.get(`${API_URL}/api/machines`).then(res => setMachines(res.data));
    axios.get(`${API_URL}/api/alerts`).then(res => setAlerts(res.data));
  }, []);

  const operando = machines.filter(m => m.status === 'operando').length;
  const falha = machines.filter(m => m.status === 'falha').length;
  const manutencao = machines.filter(m => m.status === 'manutenção').length;

  return (
    <div className="min-h-screen p-6">
      {/* Header */}
      <div className="mb-8">
        <h1 className="text-3xl font-bold text-blue-400">⚙️ SmartFactory Dashboard</h1>
        <p className="text-slate-400 mt-1">Monitoramento Industrial em Tempo Real</p>
      </div>

      {/* Cards de resumo */}
      <div className="grid grid-cols-3 gap-4 mb-8">
        <div className="bg-slate-800 rounded-xl p-4 border border-green-500/30">
          <p className="text-slate-400 text-sm">Operando</p>
          <p className="text-4xl font-bold text-green-400">{operando}</p>
        </div>
        <div className="bg-slate-800 rounded-xl p-4 border border-red-500/30">
          <p className="text-slate-400 text-sm">Em Falha</p>
          <p className="text-4xl font-bold text-red-400">{falha}</p>
        </div>
        <div className="bg-slate-800 rounded-xl p-4 border border-yellow-500/30">
          <p className="text-slate-400 text-sm">Manutenção</p>
          <p className="text-4xl font-bold text-yellow-400">{manutencao}</p>
        </div>
      </div>

      {/* Lista de máquinas */}
      <div className="bg-slate-800 rounded-xl p-6 mb-8">
        <h2 className="text-xl font-semibold mb-4 text-slate-200">🏭 Máquinas</h2>
        <div className="space-y-3">
          {machines.map(machine => (
            <div key={machine.id} className="bg-slate-700 rounded-lg p-4 flex items-center justify-between">
              <div>
                <p className="font-medium text-slate-200">{machine.name}</p>
                <p className="text-sm text-slate-400">Temp: {machine.temperature}°C | Produção: {machine.production}%</p>
              </div>
              <StatusBadge status={machine.status} />
            </div>
          ))}
        </div>
      </div>

      {/* Alertas */}
      <div className="bg-slate-800 rounded-xl p-6">
        <h2 className="text-xl font-semibold mb-4 text-slate-200">🚨 Alertas Recentes</h2>
        <div className="space-y-3">
          {alerts.map(alert => (
            <div key={alert.id} className="bg-slate-700 rounded-lg p-4">
              <p className="font-medium text-slate-200">{alert.machine}</p>
              <p className="text-sm text-slate-400">{alert.message}</p>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

export default App;
